document.addEventListener('DOMContentLoaded',function(){var nav=document.getElementById('site-navigation');if(nav){var button=nav.getElementsByTagName('button')[0];if(button){var menu=nav.getElementsByTagName('ul')[0];if(menu){if(!menu.classList.contains('nav-menu')){menu.classList.add('nav-menu');}button.addEventListener('click',function(){if(nav.classList.contains('toggled')){nav.classList.remove('toggled');button.setAttribute('aria-expanded','false');}else{nav.classList.add('toggled');button.setAttribute('aria-expanded','true');}});}}}var cartContainer=document.querySelector('.header-cart-container');if(cartContainer){var cartTrigger=cartContainer.querySelector('.cart-contents');var cartDropdown=cartContainer.querySelector('.header-mini-cart-dropdown');if(cartTrigger && cartDropdown){cartTrigger.addEventListener('click',function(e){if(window.innerWidth<=768){if(!cartDropdown.classList.contains('is-visible')){e.preventDefault();cartDropdown.classList.add('is-visible');}}});document.addEventListener('click',function(e){if(!cartContainer.contains(e.target)){cartDropdown.classList.remove('is-visible');}});}}var sliderContainers=document.querySelectorAll('.ukm-slider-container');sliderContainers.forEach(function(container){var track=container.querySelector('.ukm-slider-track');var slides=container.querySelectorAll('.ukm-slide');var prevBtn=container.querySelector('.ukm-prev');var nextBtn=container.querySelector('.ukm-next');var dots=container.querySelectorAll('.ukm-dot');var currentIndex=0;var totalSlides=slides.length;if(totalSlides<=1)return;function updateSlider(index){if(index<0)index=totalSlides-1;if(index>=totalSlides)index=0;currentIndex=index;if(track){track.style.transform='translateX(-'+(currentIndex * 100)+'%)';}dots.forEach(function(dot,i){if(i===currentIndex){dot.style.background='var(--ukm-primary)';dot.classList.add('is-active');}else{dot.style.background='var(--ukm-border-dark)';dot.classList.remove('is-active');}});}if(prevBtn){prevBtn.addEventListener('click',function(){updateSlider(currentIndex-1);});}if(nextBtn){nextBtn.addEventListener('click',function(){updateSlider(currentIndex+1);});}dots.forEach(function(dot){dot.addEventListener('click',function(){var targetIndex=parseInt(this.getAttribute('data-slide'),10);if(!isNaN(targetIndex)){updateSlider(targetIndex);}});});var autoPlay=setInterval(function(){updateSlider(currentIndex+1);},5000);container.addEventListener('mouseenter',function(){clearInterval(autoPlay);});container.addEventListener('mouseleave',function(){autoPlay=setInterval(function(){updateSlider(currentIndex+1);},5000);});});});